import pyomo.environ as pyo

DATA = {
    "products": ["A", "B"],
    "resources": ["material", "mrna"],
    # per-dose usage: usage[resource][product]
    "usage": {
        "material": {"A": 30, "B": 40},
        "mrna": {"A": 50, "B": 30},
    },
    "availability": {"material": 300, "mrna": 400},
    "max_doses_A": 5,
    "big_bound_B": 1000,          # finite upper bound for B (no explicit limit given)
    "people_per_dose": {"A": 12, "B": 8},
    "B_exceeds_A_by": 1,          # B >= A + 1  (B strictly larger than A)
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    # --- Variables ---
    def doses_bounds(m, p):
        if p == "A":
            return (0, d["max_doses_A"])
        return (0, d["big_bound_B"])

    model.doses = pyo.Var(model.P, domain=pyo.NonNegativeIntegers,
                          bounds=doses_bounds)

    # --- Objective: maximize total people treated ---
    def obj_rule(m):
        return sum(d["people_per_dose"][p] * m.doses[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # --- Constraints ---
    # Resource availability: one constraint per resource
    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.doses[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    # B must be strictly larger than A (integer => B >= A + 1)
    def b_exceeds_a_rule(m):
        return m.doses["B"] - m.doses["A"] >= d["B_exceeds_A_by"]

    model.b_exceeds_a = pyo.Constraint(rule=b_exceeds_a_rule)

    return model


